### 1. The Web Worker Logic (`worker.js`)

We need a separate file to handle the heavy lifting. This file will be imported as a module.

**File:** `src/worker/parse-csv.ts`

```typescript
import { parse } from 'csv-parse/sync';

// This function runs inside the Web Worker
export function parseCSVFile(file: File): Promise<string[]> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (event) => {
      try {
        const text = event.target?.result as string;

        // Parse the CSV
        const records = parse(text, {
          columns: true,
          skip_empty_lines: true,
          trim: true,
        });

        // Convert to array of objects (standard CSV format)
        resolve(records);
      } catch (error) {
        reject(error);
      }
    };

    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsText(file);
  });
}
```

