malloc, calloc and realloc are the three most important functions in C. They are used to allocate memory dynamically.

malloc is used to allocate memory for a single object.

calloc is used to allocate memory for an array of objects.

realloc is used to resize the memory block allocated by malloc or calloc.

Here is an implementation of these three functions in C:

malloc:

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void* malloc(size_t size) {
// Allocate memory from the heap
void* ptr = malloc(size);
// Check if the allocation was successful
if (ptr == NULL) {
return NULL;
}
// Return the pointer to the allocated memory
return ptr;
}

calloc:

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void* calloc(size_t num, size_t size) {
// Allocate memory from the heap
void* ptr = malloc(num * size);
// Check if the allocation was successful
if (ptr == NULL) {
return NULL;
}
// Set the memory to zero
memset(ptr, 0, num * size);
// Return the pointer to the allocated memory
return ptr;
}

realloc:

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void* realloc(void* ptr, size_t size) {
// Check if the pointer is NULL
if (ptr == NULL) {
return malloc(size);
}
// Allocate new memory from the heap
void* new_ptr = malloc(size);
// Check if the allocation was successful
if (new_ptr == NULL) {
return NULL;
}
// Copy the old memory to the new memory
memcpy(new_ptr, ptr, size);
// Free the old memory
free(ptr);
// Return the pointer to the new memory
return new_ptr;
}

