println!("Diff: {:?}", diff); // Output: Vector2 { x: -2.0, y: -2.0 }

// Scalar Multiplication
let scaled = a * 2.0;
println!("Scaled: {:?}", scaled); // Output: Vector2 { x: 2.0, y: 4.0 }

